// The newest valid row of the Jessie Reference Cache data table (same check as main's Reference Snapshot).
function readCache(rows) {
  let best = null;
  for (const r of rows || []) {
    if (!r || r.cache_key !== 'jessie-reference') continue;
    let d; try { d = JSON.parse(r.payload); } catch (e) { continue; }
    if (!d || !Array.isArray(d.rooms) || !Array.isArray(d.sessionTypes) || !Array.isArray(d.bookers)) continue;
    const at = Date.parse(r.refreshed_at || '') || 0;
    if (!best || at > best.at) best = { at, d };
  }
  return best ? best.d : null;
}

// Booking rows (v11): a booking in a message is a section (block_id bk_<id>) and its Change / Cancel buttons (bka_<id>).
// The buttons carry the booking: {id, d: YYYY-MM-DD, s / e: HH:MM (Manila), r: room, t: title}.
const _DS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'], _MS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const _DL = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'], _ML = ['January','February','March','April','May','June','July','August','September','October','November','December'];
function t12(hm) { if (!hm) return ''; let [h, m] = String(hm).split(':').map(Number); const ap = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12; return h + ':' + String(m).padStart(2, '0') + ' ' + ap; }
function dayShort(d) { const x = new Date(d + 'T12:00:00Z'); return _DS[x.getUTCDay()] + ', ' + _MS[x.getUTCMonth()] + ' ' + x.getUTCDate(); }
function dayLong(d) { const x = new Date(d + 'T12:00:00Z'); return _DL[x.getUTCDay()] + ', ' + _ML[x.getUTCMonth()] + ' ' + x.getUTCDate() + ', ' + x.getUTCFullYear(); }
function addDays(d, n) { return new Date(Date.parse(d + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10); }
function whenLine(b) { return dayShort(b.d) + ' · ' + (b.s && !(b.s === '00:00' && b.e === '00:00') ? t12(b.s) + ' – ' + t12(b.e) : 'all day') + (b.r ? ' · ' + roomMain(b.r) + (roomHold(b.r) ? ' + ' + roomHold(b.r) : '') : ''); }
function bkValue(b) { return JSON.stringify({ id: b.id, d: b.d, s: b.s || '', e: b.e || '', r: b.r || '', t: String(b.t || '').slice(0, 150) }); }
function bkButtons(b) {
  const pt = x => ({ type: 'plain_text', text: x });
  return { type: 'actions', block_id: 'bka_' + b.id, elements: [
    { type: 'button', action_id: 'bk_change', value: bkValue(b), text: pt('Change') },
    { type: 'button', action_id: 'bk_cancel', style: 'danger', value: bkValue(b), text: pt('Cancel'),
      confirm: { title: pt('Cancel this booking?'), text: { type: 'mrkdwn', text: ('*' + b.t + '*\n' + whenLine(b)).slice(0, 290) },
                 confirm: pt('Cancel booking'), deny: pt('Keep it'), style: 'danger' } } ] };
}
// v21: a booking's rooms - the first is the studio, a later studio / M booth is its booth ("Studio F + Studio A"),
// any other later room is a holding room
function roomList(r) { return String(r || '').split(',').map(x => x.trim()).filter(Boolean); }
function roomMain(r) { const a = roomList(r); return [a[0]].concat(a.slice(1).filter(x => /^(?:Studio\s|M\d)/i.test(x))).filter(Boolean).join(' + '); }
function roomHold(r) { return roomList(r).slice(1).filter(x => !/^(?:Studio\s|M\d)/i.test(x)).join(', '); }
function roomExtras(r) { return roomList(r).slice(1); }
function bkCard(b, head) { return head + '\n\n*' + b.t + '*\n*Date:* ' + dayLong(b.d) + '\n*Time:* ' + (b.s && !(b.s === '00:00' && b.e === '00:00') ? t12(b.s) + ' – ' + t12(b.e) : 'All day') + '\n*Room:* ' + (roomMain(b.r) || '-') + (roomHold(b.r) ? '\n*Holding room:* ' + roomHold(b.r) : ''); }
// a Google event -> a booking (Manila times; the room from its room attendee, else its location)
// v19: a calendar room label ("KDC Plaza-Top Level-Likha (Big Room)") -> the room's own name ("Likha")
function roomName(x) { return String(x || '').replace(/^KDC Plaza-Top Level-/i, '').replace(/(?:\s*\([^)]*\))+\s*$/, '').trim(); }   // v22: "Likha (Big Room) (12)" -> Likha
function evRoom(e) { const r = (e.attendees || []).filter(a => a.resource || /@resource\.calendar\.google\.com$/i.test(String(a.email || '')))
  .map(a => roomName(a.displayName)).filter(Boolean);
  // v22: Google lists the rooms in its own order - the booking's "Rooms:" line keeps studio, booth, holding rooms
  const w = (String(e.description || '').match(/(?:^|\|)\s*Rooms:\s*([^|\n]+)/i) || [])[1];
  if (w && r.length) { const o = w.split(',').map(x => x.trim()).filter(Boolean), lc = a => a.map(x => x.toLowerCase()).sort().join();
    if (lc(o) === lc(r)) return r.slice().sort((x, y) => o.findIndex(z => z.toLowerCase() === x.toLowerCase()) - o.findIndex(z => z.toLowerCase() === y.toLowerCase())).join(', '); }
  return r.length ? r.join(', ') : roomName(e.location); }
function evBooking(e) {
  const sd = e.start && e.start.dateTime, ed = e.end && e.end.dateTime;
  const m = x => { const d = new Date(new Date(x).getTime() + 8 * 3600000); return { d: d.toISOString().slice(0, 10), hm: d.toISOString().slice(11, 16) }; };
  if (sd) { const a = m(sd), b = m(ed); return { id: e.id, d: a.d, s: a.hm, e: b.hm, r: evRoom(e), t: e.summary || '(no title)' }; }
  return { id: e.id, d: String((e.start && e.start.date) || ''), s: '', e: '', r: evRoom(e), t: e.summary || '(no title)' };
}

// Notices (v18, Howard 15 Oct): the engineer / arranger is told when someone else books them or adds them in a change.
// During QA every notice goes to Howard unless the person is on ALLOW - DEV_REDIRECT = '' at launch (one constant in
// scripts/build-slack-interactions-v18.py NOTICE_JS; it is in Booked Notices, Series Notices and Change Notices).
const DEV_REDIRECT = 'U08V3CKDGJF';                 // '' at launch
const ALLOW = ['U08V3CKDGJF','U098UFMKQHZ','U08JL17A50A','U0B4S0EKSAY','U098UFLG70B','U026N6E1R','U045A3VQER3'];   // Howard, Trish, Camy, Jess, Tel, Tara, Genzo
function notices(list, actorId, actorName, body, bk) {   // v19: bk = the booking -> its own Change / Cancel
  const out = [], seen = new Set();
  for (const x of list) {
    if (!x || !x.id || x.id === actorId || seen.has(x.id)) continue; seen.add(x.id);
    const to = (!DEV_REDIRECT || ALLOW.indexOf(x.id) !== -1) ? x.id : DEV_REDIRECT;
    const text = (to !== x.id ? '[DEV] would notify ' + (x.name || x.id) + ' (' + x.id + '):\n' : '') + '👋 *' + actorName + ' ' + x.verb + ' you as the ' + x.role + (x.extra || '') + '.*\n\n' + body;
    const nav = { type: 'actions', elements: [{ type: 'button', action_id: 'my_bookings', value: 'menu', text: { type: 'plain_text', text: 'My bookings' } },
        { type: 'button', action_id: 'open_book', value: 'menu', text: { type: 'plain_text', text: 'Book a room' } }] };
    const head = text.slice(0, text.length - body.length).trim();
    const blocks = bk && bk.id ? [{ type: 'section', text: { type: 'mrkdwn', text: head } }, { type: 'section', block_id: 'bk_' + bk.id, text: { type: 'mrkdwn', text: body.slice(0, 2900) } }, bkButtons(bk), nav]
      : [{ type: 'section', text: { type: 'mrkdwn', text: text.slice(0, 2900) } }, nav];
    out.push({ json: { channel: to, text: text.slice(0, 2900), blocks } });
  }
  return out;
}
function whoIs(data, id) { const f = ((data && data.bookers) || []).map(x => x.fields || {}).find(f => String(f['Slack User ID'] || '').split(/[\s,]+/).indexOf(id) !== -1) || {};
